m5 = K(100.0, [100.6, 101.3, 100.9, 101.8, 102.6, 102.2, 103.1, 103.6, 103.0, 102.4, 102.9, 103.4])
lo = min(k[2] for k in m5); hi = max(k[1] for k in m5)
Y = lambda v: 300 - (v - lo) / (hi - lo) * 230
FONT = 'font-family="Manrope,system-ui,sans-serif" font-weight="700"'
s = ['<svg viewBox="0 0 720 380" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="12 свічок M5 складають одну свічку H1">',
     '<rect width="720" height="380" rx="18" fill="#0b0820"/>']
s.append(f'<g stroke="#a99fcc" stroke-opacity=".5" stroke-dasharray="4 5"><line x1="30" x2="640" y1="{Y(hi):.1f}" y2="{Y(hi):.1f}"/><line x1="30" x2="640" y1="{Y(lo):.1f}" y2="{Y(lo):.1f}"/></g>')
for i, (o, h, l, c) in enumerate(m5):
    x = 50 + i * 28; col = '#3fe0a0' if c >= o else '#ff6b8a'
    s.append(f'<line x1="{x}" x2="{x}" y1="{Y(h):.1f}" y2="{Y(l):.1f}" stroke="{col}" stroke-width="1.6"/>')
    s.append(f'<rect x="{x-8}" y="{Y(max(o,c)):.1f}" width="16" height="{max(2,Y(min(o,c))-Y(max(o,c))):.1f}" rx="1.5" fill="{col}"/>')
o, c = m5[0][0], m5[-1][3]
s.append(f'<line x1="580" x2="580" y1="{Y(hi):.1f}" y2="{Y(lo):.1f}" stroke="#3fe0a0" stroke-width="3"/>')
s.append(f'<rect x="550" y="{Y(c):.1f}" width="60" height="{Y(o)-Y(c):.1f}" rx="4" fill="#3fe0a0"/>')
s.append('<path d="M410 175 H500 M488 165 L502 175 L488 185" stroke="#cdbdff" stroke-width="3" fill="none"/>')
s.append(f'<g {FONT} font-size="18" text-anchor="middle"><text x="204" y="350" fill="#f1ecff">12 свічок M5 (по 5 хв)</text><text x="580" y="350" fill="#3fe0a0">1 свічка H1</text></g>')
s.append(f'<g {FONT} font-size="16" fill="#a99fcc"><text x="650" y="{Y(hi)+5:.1f}">макс.</text><text x="650" y="{Y(lo)+5:.1f}">мін.</text></g>')
s.append('</svg>')
svg1 = ''.join(s)

